import QRCode from "qrcode";

/** Server-rendered QR code (SVG). `value` is our own check-in URL. */
export async function QrCode({ value, size = 240, label }: { value: string; size?: number; label: string }) {
  const svg = await QRCode.toString(value, { type: "svg", margin: 1, errorCorrectionLevel: "M", width: size });
  return (
    <div
      role="img"
      aria-label={label}
      className="mx-auto w-fit rounded-xl bg-white p-3"
      style={{ width: size + 24 }}
      // the SVG is generated by the qrcode library from a URL we built; no user HTML
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
